import json,sys
f,out=sys.argv[1],sys.argv[2]
o=open(out,'w')
def txt(c):
    if isinstance(c,str): return c
    return ' '.join(b.get('text','') for b in c if isinstance(b,dict) and b.get('type')=='text')
pend={}
i=0
for line in open(f):
    i+=1
    try:d=json.loads(line)
    except: continue
    t=d.get('type');ts=(d.get('timestamp') or '')[5:19]
    m=d.get('message') or {}
    c=m.get('content')
    if t=='user':
        if isinstance(c,str):
            if not c.startswith('<'): o.write(f'\n#{i} {ts} USER: {c[:1500]}\n')
            else: o.write(f'\n#{i} {ts} USERSYS: {c[:300]}\n')
        elif isinstance(c,list):
            for b in c:
                if b.get('type')=='text' and not b['text'].startswith('<'):
                    o.write(f'\n#{i} {ts} USER: {b["text"][:1500]}\n')
                elif b.get('type')=='tool_result':
                    tid=b.get('tool_use_id')
                    if tid in pend:
                        o.write(f'#{i} {ts}   RESULT[{pend.pop(tid)}]: {txt(b.get("content"))[:1800]}\n')
    elif t=='assistant' and isinstance(c,list):
        for b in c:
            if b.get('type')=='text' and b['text'].strip():
                o.write(f'#{i} {ts} ASSIST: {b["text"][:700]}\n')
            elif b.get('type')=='tool_use' and b['name'] in('Agent','Task'):
                inp=b['input'];pend[b['id']]=inp.get('subagent_type')
                o.write(f'#{i} {ts} AGENT[{inp.get("subagent_type")}] {inp.get("description")}: {str(inp.get("prompt"))[:1200]}\n')
            elif b.get('type')=='tool_use' and b['name']=='Skill':
                o.write(f'#{i} {ts} SKILL {json.dumps(b["input"])[:200]}\n')
